/** Commits after `sha` on the first-parent chain of HEAD, oldest first. Only descendants of `sha` qualify. */
function laterCommits(repo: string, sha: string): Commit[] {
  const out = git(repo, [
    "log",
    "--first-parent",
    "--ancestry-path",
    "--topo-order",
    "--reverse",
    "--format=%H %P%x1f%B%x1e",
    `${sha}..HEAD`,
  ]);
  return out
    .split("\x1e")
    .filter((rec) => rec.trim() !== "")
    .map((rec) => {
      const [head = "", body = ""] = rec.split("\x1f");
      const [commit = "", ...parents] = head.trim().split(" ");
      return { sha: commit, parent: parents[0] ?? EMPTY_TREE, body };
    });
}

